const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');}));document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.remove('active');x.setAttribute('aria-pressed','false');});b.classList.add('active');b.setAttribute('aria-pressed','true');document.querySelectorAll('[data-category]').forEach(c=>c.hidden=b.dataset.filter!=='all'&&c.dataset.category!==b.dataset.filter);}));document.querySelectorAll('[data-select]').forEach(a=>a.addEventListener('click',()=>document.querySelector('#experience').value=a.dataset.select));document.querySelectorAll('[data-tour]').forEach(b=>b.addEventListener('click',()=>{document.querySelector('#experience').value=b.dataset.tour;document.querySelector('#booking').scrollIntoView({behavior:'smooth'});}));const date=document.querySelector('#date');const now=new Date();const dubaiParts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Dubai',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now);date.min=['year','month','day'].map(key=>dubaiParts.find(p=>p.type===key).value).join('-');document.querySelector('#trip-form').addEventListener('submit',e=>{e.preventDefault();if(!e.target.reportValidity())return;const text=`Hello Phoenix Tours! I'd like to request a booking.\nName: ${document.querySelector('#guest-name').value.trim()}\nTour: ${document.querySelector('#experience').value}\nDate: ${date.value}\nGuests: ${document.querySelector('#guests').value}\nHotel / pickup area: ${document.querySelector('#pickup').value.trim() || 'To be discussed'}\nPayment: on arrival.\nPlease confirm availability, total price, inclusions, pickup arrangements and accepted payment methods. I understand this request is subject to your confirmation.`;window.open('https://wa.me/971561505270?text='+encodeURIComponent(text),'_blank','noopener');});document.querySelector('#year').textContent=now.getFullYear();
